WITH kept_keys AS (SELECT order_id FROM shipments INTERSECT SELECT order_id FROM shipments WHERE order_id IN (2, 35)), verified AS (SELECT s.* FROM shipments s JOIN kept_keys k ON s.order_id = k.order_id) SELECT DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, COUNT_IF(carrier = 'UPS') AS ups_events, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'LOST' THEN 1 END), 0), 2) AS cost_per_lost FROM verified GROUP BY quarter_start HAVING COUNT_IF(carrier = 'UPS') > 1 ORDER BY ups_events NULLS FIRST
